// ============================================
// PRICING ENGINE — Arcadia Tours
// Reads from webhook body, returns 3 packages
// ============================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const SUPABASE_KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const DEFAULT_RATES = { RUB: 90, KZT: 498, PLN: 4 };

// ── Supabase helpers ────────────────────────────────────────────────────────
async function sbGet(table, q) {
  return this.helpers.httpRequest({
    url: `${SUPABASE_URL}/${table}${q ? '?' + q : ''}`,
    method: 'GET',
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${SUPABASE_KEY}`, Accept: 'application/json' }
  });
}

// ── FX Rates ────────────────────────────────────────────────────────────────
async function getRates() {
  try {
    const d = await this.helpers.httpRequest({ url: 'https://open.er-api.com/v6/latest/USD', method: 'GET' });
    if (d && d.rates) return { RUB: Math.round(d.rates.RUB) || DEFAULT_RATES.RUB, KZT: Math.round(d.rates.KZT) || DEFAULT_RATES.KZT, PLN: Math.round(d.rates.PLN) || DEFAULT_RATES.PLN };
  } catch(e) {}
  return { ...DEFAULT_RATES };
}

function toUSD(v, cur, r) { return cur === 'USD' ? v : v / (r[cur] || 1); }

// ── Data fetchers ────────────────────────────────────────────────────────────
async function getHotels(country, city) {
  let q = `Country=eq.${country}&Status=eq.Active`;
  if (city) q += `&City=eq.${encodeURIComponent(city)}`;
  return sbGet.call(this, 'hotels', q);
}

async function getRooms(hids) {
  if (!hids.length) return [];
  return sbGet.call(this, 'room_types', `Hotel_ID=in.(${hids.join(',')})`);
}

async function getSeasons(hids, date) {
  if (!hids.length || !date) return [];
  return sbGet.call(this, 'seasons', `Hotel_ID=in.(${hids.join(',')})&Start_Date=lte.${date}&End_Date=gte.${date}`);
}

async function getRatePlans(hids, sids) {
  if (!hids.length || !sids.length) return [];
  return sbGet.call(this, 'rate_plans', `Hotel_ID=in.(${hids.join(',')})&Season_ID=in.(${sids.join(',')})&Status=eq.Active&Meal_Plan=eq.BB`);
}

async function getServices(country, city) {
  const svcCity = city === 'Almaty Region' ? 'Almaty' : city;
  return sbGet.call(this, 'services', `Country=eq.${country}&City=eq.${encodeURIComponent(svcCity)}`);
}

// ── Helper utils ─────────────────────────────────────────────────────────────
function addDays(d, n) { const dt = new Date(d + 'T12:00:00'); dt.setDate(dt.getDate() + n); return dt.toISOString().slice(0, 10); }

function pickVehicle(svcs, cat, pax) {
  return svcs.filter(s => s.Category === cat && (s.Max_Persons || 99) >= pax)
             .sort((a, b) => a.Price - b.Price)[0] || null;
}

function findSeason(seasons, hid, date) {
  const d = new Date(date + 'T12:00:00'), day = d.getDay(), isWE = [0, 1, 5, 6].includes(day);
  const m = seasons.filter(s => s.Hotel_ID === hid);
  const dayType = isWE ? 'Weekend' : 'Weekday';
  const typed = m.filter(s => s.Season_Name && s.Season_Name.includes(dayType)).sort((a, b) => (b.Priority || 0) - (a.Priority || 0));
  return typed[0] || m.sort((a, b) => (b.Priority || 0) - (a.Priority || 0))[0] || null;
}

function occRate(rate, occ) {
  if (!rate) return 0;
  if (occ === 'SGL') return parseFloat(rate.SGL_Rate) || 0;
  if (occ === 'DBL') return parseFloat(rate.DBL_Rate) || 0;
  if (occ === 'TRP') return parseFloat(rate.TRP_Rate) || 0;
  return 0;
}

function defaultRoomConfig(adults) {
  if (adults <= 1) return { rooms: [{ occ: 'SGL', count: 1 }], label: 'مفردة' };
  if (adults === 2) return { rooms: [{ occ: 'DBL', count: 1 }], label: 'مزدوجة' };
  if (adults === 3) return { rooms: [{ occ: 'TRP', count: 1 }], label: 'ثلاثية' };
  if (adults === 4) return { rooms: [{ occ: 'DBL', count: 2 }], label: '2 مزدوجة' };
  if (adults === 5) return { rooms: [{ occ: 'TRP', count: 1 }, { occ: 'DBL', count: 1 }], label: 'ثلاثية+مزدوجة' };
  return { rooms: [{ occ: 'DBL', count: Math.ceil(adults / 2) }], label: `${Math.ceil(adults / 2)} مزدوجة` };
}

function calcHotel(hotel, rooms, rates, seasons, cfg, nights, childAges, date, exR) {
  const season = findSeason(seasons, hotel.Hotel_ID, date);
  if (!season || ['Blackout','Closed','Special'].includes(season.Season_Type)) return null;
  const hRooms = rooms.filter(r => r.Hotel_ID === hotel.Hotel_ID);
  let total = 0, bestRoomName = '', bestRoomCategory = '';

  for (const rc of cfg.rooms) {
    let best = null;
    for (const room of hRooms) {
      const maxA = parseInt(room.Max_Adults) || 2;
      if (rc.occ === 'TRP' && maxA < 3) continue;
      if (rc.occ === 'DBL' && maxA < 2) continue;
      const rate = rates.find(r => r.Hotel_ID === hotel.Hotel_ID && r.Room_ID === room.Room_ID && r.Season_ID === season.Season_ID);
      if (!rate) continue;
      const nr = occRate(rate, rc.occ);
      if (!nr) continue;
      let childEx = 0;
      if (rc.count === 1) for (const age of (childAges || [])) {
        if (age <= 5) childEx += parseFloat(rate.Extra_Child_0_5 || 0);
        else if (age <= 11) childEx += parseFloat(rate.Extra_Child_6_11 || 0);
        else childEx += parseFloat(rate.Extra_Adult || 0);
      }
      const usd = toUSD((nr + childEx) * nights, hotel.Currency, exR);
      if (!best || usd < best.usd) best = { usd, room, occ: rc.occ };
    }
    if (!best) return null;
    total += best.usd * rc.count;
    if (!bestRoomName) { bestRoomName = best.room.Room_Type_Name || 'Standard'; bestRoomCategory = best.room.Room_Category || ''; }
  }
  return { totalUSD: total, roomName: bestRoomName, roomCategory: bestRoomCategory };
}

// ── Inclusions builder ───────────────────────────────────────────────────────
function buildInclusions(destination, city, nights, tours, hasSIM, withGuide, isMultiCity) {
  const tourDays = Math.max(nights - 1, 1);
  const effectiveTours = tours !== null ? tours : tourDays;
  const cityNames = { Almaty: 'ألماتي', Moscow: 'موسكو', 'Saint Petersburg': 'سانت بطرسبرغ', 'Almaty Region': 'المنتجع' };
  const repCity = cityNames[city] || city;
  const items = [
    '🏨 الإقامة في الفندق مع الإفطار اليومي',
    '🚗 الاستقبال والتوصيل من وإلى المطار',
  ];
  if (effectiveTours > 0) items.push(`🗺️ ${effectiveTours} جولة سياحية بسيارة خاصة مع سائق`);
  items.push('🎧 خدمة عملاء أركاديا على مدار الساعة');
  if (hasSIM) items.push('📱 شريحة اتصال وإنترنت محلية');
  if (withGuide && effectiveTours > 0) items.push('👨‍🏫 مرشد سياحي عربي');
  items.push(`👨‍💼 مندوب أركاديا في ${repCity} لمتابعتكم`);
  return items;
}

// ── Main buildPkgs ───────────────────────────────────────────────────────────
async function buildPkgs(params) {
  const {
    destination, city, nights, adults,
    childrenAges = [], clientType = 'B2C',
    roomConfig = null, withGuide = false,
    checkIn = null, tours = null, exclude = []
  } = params;
  params.exclude = exclude;

  const DEST_META = {
    KZ: { country: 'Kazakhstan', currency: 'KZT', hasSIM: true },
    RU: { country: 'Russia',     currency: 'RUB', hasSIM: false },
    PL: { country: 'Poland',     currency: 'PLN', hasSIM: true },
    UZ: { country: 'Uzbekistan', currency: 'UZS', hasSIM: true }
  };

  const meta = DEST_META[destination];
  if (!meta) throw new Error(`Unknown destination: ${destination}`);

  const markup    = clientType === 'B2B' ? 1.15 : 1.20;
  const cfg       = roomConfig || defaultRoomConfig(adults);
  const date      = checkIn || new Date().toISOString().slice(0, 10);
  const exR       = await getRates.call(this);
  const effectiveTours = tours !== null ? tours : Math.max(nights - 1, 1);

  // Fetch data
  const hotels  = await getHotels.call(this, meta.country, city);
  const hids    = hotels.map(h => h.Hotel_ID);
  const rooms   = await getRooms.call(this, hids);
  const seasAll = await getSeasons.call(this, hids, date);
  const validS  = seasAll.filter(s => !['Blackout','Closed','Special'].includes(s.Season_Type));
  const sids    = validS.map(s => s.Season_ID);
  const rates   = await getRatePlans.call(this, hids, sids);
  const svcs    = await getServices.call(this, meta.country, city);

  // Services cost (shared for all tiers)
  // route=basic → hotel + breakfast + airport transfer only (no tours, no SIM)
  const isBasic = (params.route === 'basic');
  const pax = adults + childrenAges.length;
  let svcUSD = 0;
  if (!isBasic && effectiveTours > 0) {
    const car = pickVehicle(svcs, 'Daily_Rent_8h', pax);
    if (car) svcUSD += toUSD(car.Price * effectiveTours, car.Currency || meta.currency, exR);
  }
  const tf = pickVehicle(svcs, 'Transfer_Airport', pax);
  if (tf) svcUSD += toUSD(tf.Price * 2, tf.Currency || meta.currency, exR);
  if (!isBasic && meta.hasSIM) {
    const sim = svcs.find(s => s.Category === 'SIM_Card');
    if (sim) svcUSD += toUSD(sim.Price * adults, sim.Currency || meta.currency, exR);
  }
  if (!isBasic && withGuide && effectiveTours > 0) {
    const g = svcs.find(s => s.Category === 'Guide_Daily');
    if (g) svcUSD += toUSD(g.Price * effectiveTours, g.Currency || meta.currency, exR);
  }

  // ── ranked() — exact copy from Calculator Bot ─────────────────────────────
  function ranked(starFilter, nightsN) {
    const hotelList = hotels.filter(h => h.Star_Rating === starFilter && h.Status === 'Active');
    const res = [];
    for (const h of hotelList) {
      const c = calcHotel(h, rooms, rates, validS, cfg, nightsN, childrenAges, date, exR);
      if (c) res.push({ hotel: h, cost: c, total: Math.round((c.totalUSD + svcUSD) * markup), roomName: c.roomName });
    }
    return res.sort((a, b) => a.total - b.total);
  }

  // ── Tiers — exact same logic as Calculator Bot ───────────────────────────
  const TIERS = [
    { key: 'eco',    ar: 'اقتصادية', stars: 4, pick: 'first'  },
    { key: 'silver', ar: 'فضية',     stars: 4, pick: 'median' },
    { key: 'gold',   ar: 'ذهبية',    stars: 5, pick: 'first'  }
  ];

  const includes = isBasic
    ? ['🏨 الإقامة في الفندق مع الإفطار اليومي', '🚗 الاستقبال والتوديع من المطار', '🎧 خدمة عملاء أركاديا على مدار الساعة']
    : buildInclusions(destination, city, nights, effectiveTours, meta.hasSIM, withGuide, false);
  const packages = [];
  const usedHotels = new Set();

  const excludeList = params.exclude || [];
  for (const tier of TIERS) {
    const r = ranked(tier.stars, nights).filter(h => !excludeList.some(ex => h.hotel.Hotel_Name.toLowerCase().includes(ex)));
    if (!r.length) continue;
    let idx = tier.pick === 'first' ? 0 : Math.floor(r.length / 2);
    // skip duplicates
    while (idx < r.length && usedHotels.has(r[idx].hotel.Hotel_ID)) idx++;
    if (idx >= r.length) continue;
    const s = r[idx];
    usedHotels.add(s.hotel.Hotel_ID);

    packages.push({
      tier:        tier.key,
      tierAr:      tier.ar,
      hotelName:   s.hotel.Hotel_Name,
      hotelNameAr: s.hotel.Hotel_Name_AR || s.hotel.Hotel_Name,
      stars:       s.hotel.Star_Rating || tier.stars,
      city,
      nights,
      roomType:    s.roomName,
      mealPlan:    'إفطار يومي',
      totalUSD:    s.total,
      includes
    });
  }

  return packages;
}

// ══════════════════════════════════════════════════════
// MAIN — Read from webhook body
// ══════════════════════════════════════════════════════
const raw   = $input.first().json;
const input = raw.body || raw;

const params = {
  destination:   input.destination  || 'KZ',
  city:          input.city         || 'Almaty',
  nights:        parseInt(input.nights)  || 7,
  adults:        parseInt(input.adults)  || 2,
  childrenAges:  input.childrenAges || [],
  clientType:    input.clientType   || 'B2C',
  roomConfig:    input.roomConfig   || null,
  withGuide:     input.guide        || false,
  checkIn:       input.checkIn      || null,
  tours:         input.tours        !== undefined ? parseInt(input.tours) : null,
  route:         input.route        || 'standard',
  segments:      Array.isArray(input.segments) ? input.segments : null,
  hotelName:     input.hotelName    || null,
  roomCategory:  input.roomCategory || null,
  exclude:       Array.isArray(input.exclude) ? input.exclude.map(s=>s.toLowerCase().trim()) : []
};

if (!params.destination || !params.nights || !params.adults) {
  return [{ json: { error: 'Missing required: destination, nights, adults' } }];
}


// ══════════════════════════════════════════════════════════
// MULTI-CITY MODE
// params.segments = [{city, nights, tours?}, ...]
// ══════════════════════════════════════════════════════════
async function buildMultiCityPkgs(params) {
  const { destination, segments, adults, childrenAges = [], clientType = 'B2C',
          roomConfig = null, withGuide = false, checkIn = null } = params;

  const DEST_META = {
    KZ: { country: 'Kazakhstan', currency: 'KZT', hasSIM: true },
    RU: { country: 'Russia',     currency: 'RUB', hasSIM: false }
  };
  const meta = DEST_META[destination];
  if (!meta) throw new Error('Unknown destination for multi-city: ' + destination);

  const markup  = clientType === 'B2B' ? 1.15 : 1.20;
  const exR     = await getRates.call(this);
  const date    = checkIn || new Date().toISOString().slice(0, 10);
  const totalPax = adults + childrenAges.length;
  const cfg     = roomConfig || defaultRoomConfig(adults);

  // Fetch all hotels + services for all unique cities
  const uniqCities = [...new Set(segments.map(s => s.city))];
  let allH = [], allSvc = {};
  for (const city of uniqCities) {
    const h = await getHotels.call(this, meta.country, city);
    allH = allH.concat(h);
    allSvc[city] = await getServices.call(this, meta.country, city);
  }
  const hids   = allH.map(h => h.Hotel_ID);
  const allRm  = await getRooms.call(this, hids);
  const allSea = await getSeasons.call(this, hids, date);
  const validS = allSea.filter(s => !['Blackout','Closed','Special'].includes(s.Season_Type));
  const sids   = validS.map(s => s.Season_ID);
  const allRP  = await getRatePlans.call(this, hids, sids);

  function rankedCity(city, stars, nights) {
    const hotelList = allH.filter(h => h.City === city && h.Star_Rating === stars && h.Status === 'Active');
    const res = [];
    for (const h of hotelList) {
      const c = calcHotel(h, allRm, allRP, validS, cfg, nights, childrenAges, date, exR);
      if (c) res.push({ hotel: h, cost: c });
    }
    return res.sort((a, b) => a.cost.totalUSD - b.cost.totalUSD);
  }

  // Shared costs (airport + train) — added once, split across segments
  const firstCity  = segments[0].city;
  const firstSvcs  = allSvc[firstCity] || [];
  const numSegments = segments.length;

  function sharedCost() {
    let t = 0;
    // Airport transfers: arrival + departure (always from first city)
    const tf = pickVehicle(firstSvcs, 'Transfer_Airport', totalPax);
    if (tf) t += toUSD(tf.Price, tf.Currency || meta.currency, exR) * 2;
    // Train tickets (Russia only)
    if (destination === 'RU') {
      const trainSvc = firstSvcs.find(s => s.Category === 'Train_Ticket' || s.Category === 'train tickets');
      const tp = trainSvc ? trainSvc.Price : 4500;
      const tc = trainSvc ? trainSvc.Currency : 'RUB';
      const numTrains = numSegments - 1; // trips between cities
      t += toUSD(tp * numTrains * totalPax, tc, exR);
      // Car for train transfer days
      const trainCar = pickVehicle(firstSvcs, 'Daily_Rent_8h', totalPax);
      if (trainCar) t += toUSD(trainCar.Price * numTrains, trainCar.Currency || meta.currency, exR);
    }
    // Inter-city car for Kazakhstan resort
    if (destination === 'KZ') {
      const ic = pickVehicle(firstSvcs, 'Daily_Rent_8h', totalPax);
      if (ic) t += toUSD(ic.Price * (numSegments - 1), ic.Currency || meta.currency, exR);
    }
    return t;
  }

  const shared = sharedCost();

  const TIERS = [
    { key: 'eco',    ar: 'اقتصادية', stars: 4, pick: 'first'  },
    { key: 'silver', ar: 'فضية',     stars: 4, pick: 'median' },
    { key: 'gold',   ar: 'ذهبية',    stars: 5, pick: 'first'  }
  ];

  const packages = [];

  for (const tier of TIERS) {
    let stops = [], base = shared, curDate = date, ok = true;
    const simDone = new Set();

    for (let si = 0; si < segments.length; si++) {
      const { city, nights, tours } = segments[si];
      const svcs = allSvc[city] || [];
      const isFirst = si === 0, isLast = si === segments.length - 1;

      const r = rankedCity(city, tier.stars, nights);
      if (!r.length) { ok = false; break; }
      const chosen = tier.pick === 'first' ? r[0] : r[Math.floor(r.length / 2)];

      // Per-segment costs (no airport transfer — that's in shared)
      const effectiveTours = (tours !== undefined && tours !== null) ? tours :
            (city === 'Almaty Region' ? 0 : Math.max(nights - 1, 1));

      let carUSD = 0;
      if (effectiveTours > 0) {
        const car = pickVehicle(svcs, 'Daily_Rent_8h', totalPax);
        if (car) carUSD = toUSD(car.Price * effectiveTours, car.Currency || meta.currency, exR);
      }

      let simUSD = 0;
      const simCity = city === 'Almaty Region' ? 'Almaty' : city;
      if (meta.hasSIM && !simDone.has(simCity)) {
        const sim = svcs.find(s => s.Category === 'SIM_Card') ||
                    (allSvc['Almaty'] || []).find(s => s.Category === 'SIM_Card');
        if (sim) { simUSD = toUSD(sim.Price * adults, sim.Currency || meta.currency, exR); simDone.add(simCity); }
      }

      let guideUSD = 0;
      if (withGuide && effectiveTours > 0) {
        const g = svcs.find(s => s.Category === 'Guide_Daily');
        if (g) guideUSD = toUSD(g.Price * effectiveTours, g.Currency || meta.currency, exR);
      }

      const stopTotal = chosen.cost.totalUSD + carUSD + simUSD + guideUSD;
      base += stopTotal;

      stops.push({
        city, nights, date: curDate,
        hotelName: chosen.hotel.Hotel_Name,
        hotelNameAr: chosen.hotel.Hotel_Name_AR || chosen.hotel.Hotel_Name,
        stars: chosen.hotel.Star_Rating,
        roomType: chosen.cost.roomName,
        mealPlan: chosen.cost.mealPlan || 'إفطار يومي',
        totalUSD: Math.round(stopTotal),
        tours: effectiveTours
      });
      curDate = addDays(curDate, nights);
    }

    if (!ok) continue;

    const totalUSD = Math.round(base * markup);
    packages.push({
      tier: tier.key,
      tierAr: tier.ar,
      totalUSD,
      stops,
      trainIncluded: destination === 'RU',
      nights: segments.reduce((a, s) => a + s.nights, 0)
    });
  }

  return packages;
}


// ── Hotel Mode — show all room types for a specific hotel ──────────────────
if (params.hotelName && params.roomCategory === 'all') {
  try {
    const input2 = params;
    const meta2 = { KZ:{country:'Kazakhstan',currency:'KZT',hasSIM:true}, RU:{country:'Russia',currency:'RUB',hasSIM:false}, PL:{country:'Poland',currency:'PLN',hasSIM:true}, UZ:{country:'Uzbekistan',currency:'UZS',hasSIM:true} }[input2.destination] || {country:'Kazakhstan',currency:'KZT',hasSIM:true};
    const exR2 = await getRates.call(this);
    const rate2 = exR2[meta2.currency] || 450;
    const markup2 = input2.clientType === 'B2B' ? 1.15 : 1.20;
    const date2 = input2.checkIn || new Date().toISOString().slice(0,10);

    // Find hotel by name (case-insensitive partial match)
    const allHotels = await getHotels.call(this, meta2.country, input2.city || null);
    const hotel = allHotels.find(h => h.Hotel_Name && h.Hotel_Name.toLowerCase().includes(input2.hotelName.toLowerCase()));
    if (!hotel) return [{ json: { ok: false, hotelMode: true, error: 'Hotel not found: ' + input2.hotelName } }];

    const hid = hotel.Hotel_ID;
    const allRooms = await getRooms.call(this, [hid]);
    const seasAll2 = await getSeasons.call(this, [hid], date2);
    const validS2 = seasAll2.filter(s => !['Blackout','Closed','Special'].includes(s.Season_Type));
    const sids2 = validS2.map(s => s.Season_ID);
    const allRates = await getRatePlans.call(this, [hid], sids2);

    // Services cost
    const svcs2 = await getServices.call(this, meta2.country, input2.city || 'Almaty');
    const pax2 = (input2.adults||2) + (input2.childrenAges||[]).length;
    const eff2 = (input2.tours !== undefined && input2.tours !== null) ? parseInt(input2.tours) : Math.max((input2.nights||7)-1,1);
    let svc2 = 0;
    const car2 = pickVehicle(svcs2,'Daily_Rent_8h',pax2); if(car2) svc2 += toUSD(car2.Price*eff2,car2.Currency||meta2.currency,exR2);
    const tf2 = pickVehicle(svcs2,'Transfer_Airport',pax2); if(tf2) svc2 += toUSD(tf2.Price*2,tf2.Currency||meta2.currency,exR2);
    if(meta2.hasSIM){const sim2=svcs2.find(s=>s.Category==='SIM_Card'); if(sim2) svc2+=toUSD(sim2.Price*(input2.adults||2),sim2.Currency||meta2.currency,exR2);}

    // Build room list — use Room_ID link, DBL_Rate for 2 adults
    const adults2 = input2.adults || 2;
    const occ2 = adults2 >= 3 ? 'TRP' : adults2 === 1 ? 'SGL' : 'DBL';
    const rooms2 = [];
    const seenRooms = new Set();
    const season2 = validS2.length > 0 ? validS2[0] : null;
    for (const room of allRooms) {
      const roomName = room.Room_Type_Name;
      if (seenRooms.has(roomName)) continue;
      if (parseInt(room.Max_Adults||2) < adults2) continue;
      const rate = allRates.find(r => r.Room_ID === room.Room_ID && (season2 ? r.Season_ID === season2.Season_ID : true));
      if (!rate) continue;
      const pricePerNight = parseFloat(rate[occ2 + '_Rate'] || rate.DBL_Rate || 0);
      if (!pricePerNight) continue;
      const hotelRaw = toUSD(pricePerNight, rate.Currency || meta2.currency, exR2) * (input2.nights||7);
      const totalUSD = Math.round((hotelRaw + svc2) * markup2);
      rooms2.push({ roomType: roomName, mealPlan: rate.Meal_Plan || 'BB', totalUSD });
      seenRooms.add(roomName);
    }
    rooms2.sort((a,b) => a.totalUSD - b.totalUSD);

    return [{ json: { ok: true, hotelMode: true, hotelName: hotel.Hotel_Name, stars: hotel.Star_Rating, destination: input2.destination, city: input2.city, nights: input2.nights, adults: input2.adults, rooms: rooms2 } }];
  } catch(e) {
    return [{ json: { ok: false, hotelMode: true, error: e.message } }];
  }
}

try {
  // Multi-city mode
  if (params.segments && Array.isArray(params.segments) && params.segments.length > 1) {
    const mcPackages = await buildMultiCityPkgs.call(this, params);
    return [{ json: { ok: true, multiCity: true, destination: params.destination, segments: params.segments, adults: params.adults, packages: mcPackages, noMore: mcPackages.length === 0 } }];
  }
  // Single-city mode
  const packages = await buildPkgs.call(this, params);
  return [{ json: { ok: true, destination: params.destination, city: params.city, nights: params.nights, adults: params.adults, packages, noMore: packages.length === 0 } }];
} catch(e) {
  return [{ json: { ok: false, error: e.message } }];
}
